arguments.command:
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using System.Linq;
using System.Reflection;

namespace CheckoutPricing.UnitTests;

public class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var checkoutTypes = new[] { typeof(CheckoutPricing.Application.ApplicationMarker).Assembly, typeof(CheckoutPricing.Domain.DomainMarker).Assembly }
            .SelectMany(a => a.GetTypes())
            .Where(t => t.IsPublic && t.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase))
            .ToList();

        Assert.True(checkoutTypes.Count > 0, "No checkout pricing type exists, so a Gold customer's 100.00 subtotal cannot yield 95.00.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Assert|No checkout|Passed!|Failed!" | head

